package com.example.trading;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.web.socket.config.annotation.*;
import org.springframework.web.socket.handler.TextWebSocketHandler;
import org.springframework.web.socket.*;
import org.springframework.context.annotation.Configuration;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.web.bind.annotation.*;
import org.springframework.stereotype.Component;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.JsonNode;
import java.util.concurrent.ConcurrentHashMap;
import java.util.Map;

@SpringBootApplication
public class TradingApplication {
    public static void main(String[] args) {
        SpringApplication.run(TradingApplication.class, args);
    }
}

@Configuration
@EnableWebSocket
class WebSocketConfig implements WebSocketConfigurer {
    @Autowired
    private TradeWebSocketHandler handler;

    @Override
    public void registerWebSocketHandlers(WebSocketHandlerRegistry registry) {
        // No origin check - allows cross-site WebSocket hijacking
        registry.addHandler(handler, "/ws/trades")
                .setAllowedOrigins("*");
    }
}

@Component
class TradeWebSocketHandler extends TextWebSocketHandler {
    private static final Map<String, WebSocketSession> sessions = new ConcurrentHashMap<>();
    private final ObjectMapper mapper = new ObjectMapper();

    @Autowired
    private JdbcTemplate jdbcTemplate;

    @Override
    public void afterConnectionEstablished(WebSocketSession session) {
        // Session authenticated via cookie (vulnerable to CSWSH)
        String userId = extractUserFromCookie(session);
        if (userId != null) {
            sessions.put(userId, session);
        }
    }

    @Override
    protected void handleTextMessage(WebSocketSession session, TextMessage message) throws Exception {
        String userId = extractUserFromCookie(session);
        if (userId == null) {
            session.close(CloseStatus.NOT_ACCEPTABLE);
            return;
        }

        JsonNode payload = mapper.readTree(message.getPayload());
        String action = payload.get("action").asText();

        switch (action) {
            case "get_portfolio":
                handleGetPortfolio(session, userId);
                break;
            case "place_order":
                handlePlaceOrder(session, userId, payload);
                break;
            case "cancel_order":
                handleCancelOrder(session, userId, payload);
                break;
            case "get_balance":
                handleGetBalance(session, userId);
                break;
        }
    }

    private void handleGetPortfolio(WebSocketSession session, String userId) throws Exception {
        var results = jdbcTemplate.queryForList(
            "SELECT symbol, quantity, avg_price FROM portfolio WHERE user_id = ?", userId);
        session.sendMessage(new TextMessage(mapper.writeValueAsString(results)));
    }

    private void handlePlaceOrder(WebSocketSession session, String userId, JsonNode payload) throws Exception {
        String symbol = payload.get("symbol").asText();
        int quantity = payload.get("quantity").asInt();
        String side = payload.get("side").asText();
        double price = payload.get("price").asDouble();

        // Direct SQL insert - vulnerable to data manipulation via CSWSH
        jdbcTemplate.update(
            "INSERT INTO orders (user_id, symbol, quantity, side, price, status) VALUES (?, ?, ?, ?, ?, 'PENDING')",
            userId, symbol, quantity, side, price);

        session.sendMessage(new TextMessage("{\"status\": \"order_placed\"}"));
    }

    private void handleCancelOrder(WebSocketSession session, String userId, JsonNode payload) throws Exception {
        String orderId = payload.get("order_id").asText();
        jdbcTemplate.update(
            "UPDATE orders SET status = 'CANCELLED' WHERE id = ? AND user_id = ?",
            orderId, userId);
        session.sendMessage(new TextMessage("{\"status\": \"order_cancelled\"}"));
    }

    private void handleGetBalance(WebSocketSession session, String userId) throws Exception {
        var result = jdbcTemplate.queryForMap(
            "SELECT balance, margin_used, unrealized_pnl FROM accounts WHERE user_id = ?", userId);
        session.sendMessage(new TextMessage(mapper.writeValueAsString(result)));
    }

    private String extractUserFromCookie(WebSocketSession session) {
        var cookies = session.getHandshakeHeaders().get("Cookie");
        if (cookies == null || cookies.isEmpty()) return null;
        for (String cookie : cookies.get(0).split(";")) {
            cookie = cookie.trim();
            if (cookie.startsWith("SESSION_TOKEN=")) {
                return validateSessionToken(cookie.substring(14));
            }
        }
        return null;
    }

    private String validateSessionToken(String token) {
        try {
            var results = jdbcTemplate.queryForList(
                "SELECT user_id FROM sessions WHERE token = ? AND expires_at > NOW()", token);
            return results.isEmpty() ? null : (String) results.get(0).get("user_id");
        } catch (Exception e) {
            return null;
        }
    }
}
